use std::future::Future;
use std::pin::pin;
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

// ---- You don't need to understand this helper. ----
// Rust's standard library has no runtime, so this tiny one runs a future
// to the end by polling it. Real programs use a crate such as tokio.
struct ThreadWaker(Thread);

impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }
}

fn block_on<F: Future>(future: F) -> F::Output {
    let mut future = pin!(future);
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match future.as_mut().poll(&mut cx) {
            Poll::Ready(value) => return value,
            Poll::Pending => thread::park(),
        }
    }
}

// PauseOnce is a future that answers "not ready yet" the first time it is
// asked, so that you can watch an .await pause. It is part of the helper too.
use std::pin::Pin;

struct PauseOnce {
    paused: bool,
}

impl Future for PauseOnce {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.paused {
            Poll::Ready(())
        } else {
            self.paused = true;
            cx.waker().wake_by_ref();   // "ask me again right away"
            Poll::Pending
        }
    }
}

// ---- End of helper. ----

async fn add(a: i32, b: i32) -> i32 {
    a + b
}

async fn greet(name: &str) -> String {
    println!("greet: before the pause");
    PauseOnce { paused: false }.await;
    println!("greet: after the pause");
    let sum = add(2, 3).await;
    format!("Hello, {name}! 2 + 3 = {sum}")
}

fn main() {
    println!("1: calling greet");
    let future = greet("Ada");
    println!("2: we have a future, but nothing has run yet");
    let message = block_on(future);
    println!("3: {message}");
}

// Output:
// 1: calling greet
// 2: we have a future, but nothing has run yet
// greet: before the pause
// greet: after the pause
// 3: Hello, Ada! 2 + 3 = 5

// Needs the tokio crate (Cargo.toml: tokio = { version = "1", features = ["full"] }),
// so it can't run in this app. In a real program, #[tokio::main] goes above
// an async main function, which starts the runtime and calls fetch_two_pages().await.
use std::time::Duration;

async fn fetch(name: &str) -> String {
    tokio::time::sleep(Duration::from_millis(100)).await;   // pretend to wait for the network
    format!("page {name}")
}

async fn fetch_two_pages() {
    // join! runs both futures side by side: about 100 ms in total, not 200
    let (a, b) = tokio::join!(fetch("a"), fetch("b"));
    println!("{a} and {b}");
}

